fn is_prime(n: i8) -> bool {
    // Negative numbers, 0, and 1 are not prime
    if n < 2 {
        return false;
    }
    
    // Check divisibility by numbers from 2 up to sqrt(n)
    // For i8, the maximum value is 127, so we only need to check up to 11
    let limit = (n as f32).sqrt() as i8 + 1;
    
    for i in 2..=limit {
        if n % i == 0 {
            return false;
        }
    }
    
    true
}